PRAGMA foreign_keys=ON;
CREATE TABLE company_profile(id INTEGER PRIMARY KEY CHECK(id=1),name TEXT NOT NULL,address TEXT,contact TEXT,logo_path TEXT,start_date TEXT NOT NULL);
CREATE TABLE company_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE financial_years(id TEXT PRIMARY KEY,start_date TEXT NOT NULL,end_date TEXT NOT NULL CHECK(end_date>=start_date));
CREATE TABLE number_sequences(fy TEXT REFERENCES financial_years(id),kind TEXT,next_number INTEGER NOT NULL CHECK(next_number>0),PRIMARY KEY(fy,kind));
CREATE TABLE parties(id INTEGER PRIMARY KEY,name TEXT NOT NULL,contact_person TEXT,phone TEXT,email TEXT,address TEXT,pan TEXT,gstin TEXT,credit_days INTEGER DEFAULT 0 CHECK(credit_days>=0),remarks TEXT,active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE party_roles(party_id INTEGER REFERENCES parties(id),role TEXT CHECK(role IN('supplier','customer','broker','other')),PRIMARY KEY(party_id,role));
CREATE TABLE qualities(id INTEGER PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE UNIQUE,description TEXT,hike_pct TEXT,active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE accounts(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('asset','liability','equity','income','expense')),party_id INTEGER REFERENCES parties(id),active INTEGER DEFAULT 1 CHECK(active IN(0,1)),control INTEGER DEFAULT 0 CHECK(control IN(0,1)));
CREATE TABLE bank_accounts(id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL UNIQUE REFERENCES accounts(id),bank_name TEXT NOT NULL,holder TEXT,account_number TEXT,ifsc TEXT);
CREATE TABLE journal_entries(id INTEGER PRIMARY KEY,number TEXT NOT NULL,entry_date TEXT NOT NULL,source_type TEXT NOT NULL,source_id INTEGER,narration TEXT,reference TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','posted','reversed')),reversal_of INTEGER REFERENCES journal_entries(id));
CREATE TABLE journal_lines(id INTEGER PRIMARY KEY,journal_id INTEGER NOT NULL REFERENCES journal_entries(id),account_id INTEGER NOT NULL REFERENCES accounts(id),debit INTEGER NOT NULL DEFAULT 0,credit INTEGER NOT NULL DEFAULT 0,CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE TRIGGER journal_balance BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' BEGIN SELECT CASE WHEN (SELECT count(*) FROM journal_lines WHERE journal_id=NEW.id)<2 OR (SELECT coalesce(sum(debit-credit),0) FROM journal_lines WHERE journal_id=NEW.id)<>0 THEN RAISE(ABORT,'unbalanced journal') END; END;
CREATE TRIGGER journal_draft_insert BEFORE INSERT ON journal_entries WHEN NEW.status<>'draft' BEGIN SELECT RAISE(ABORT,'insert draft first'); END;
CREATE TRIGGER journal_line_insert BEFORE INSERT ON journal_lines WHEN (SELECT status FROM journal_entries WHERE id=NEW.journal_id)<>'draft' BEGIN SELECT RAISE(ABORT,'immutable journal'); END;
CREATE TRIGGER journal_line_update BEFORE UPDATE ON journal_lines WHEN (SELECT status FROM journal_entries WHERE id=OLD.journal_id)<>'draft' OR (SELECT status FROM journal_entries WHERE id=NEW.journal_id)<>'draft' BEGIN SELECT RAISE(ABORT,'immutable journal'); END;
CREATE TRIGGER journal_line_delete BEFORE DELETE ON journal_lines WHEN (SELECT status FROM journal_entries WHERE id=OLD.journal_id)<>'draft' BEGIN SELECT RAISE(ABORT,'immutable journal'); END;
CREATE TABLE purchases(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,party_id INTEGER NOT NULL REFERENCES parties(id),bill_date TEXT NOT NULL,due_days INTEGER NOT NULL CHECK(due_days>=0),due_date TEXT NOT NULL,remarks TEXT,status TEXT NOT NULL CHECK(status IN('draft','posted','cancelled')),journal_id INTEGER REFERENCES journal_entries(id),supplier_total INTEGER NOT NULL CHECK(supplier_total>=0),stock_total INTEGER NOT NULL CHECK(stock_total>=0));
CREATE TABLE purchase_items(id INTEGER PRIMARY KEY,purchase_id INTEGER NOT NULL REFERENCES purchases(id),quality_id INTEGER NOT NULL REFERENCES qualities(id),carats INTEGER NOT NULL CHECK(carats>0),rate TEXT NOT NULL,less_pct TEXT NOT NULL,gross INTEGER NOT NULL CHECK(gross>=0),net INTEGER NOT NULL CHECK(net>=0));
CREATE TABLE purchase_expenses(id INTEGER PRIMARY KEY,purchase_id INTEGER NOT NULL REFERENCES purchases(id),description TEXT,amount INTEGER NOT NULL CHECK(amount>0),mode TEXT NOT NULL CHECK(mode IN('supplier','separate')),fund_account_id INTEGER REFERENCES accounts(id),CHECK((mode='supplier' AND fund_account_id IS NULL) OR (mode='separate' AND fund_account_id IS NOT NULL)));
CREATE TABLE purchase_expense_allocations(expense_id INTEGER REFERENCES purchase_expenses(id),item_id INTEGER REFERENCES purchase_items(id),amount INTEGER NOT NULL CHECK(amount>=0),PRIMARY KEY(expense_id,item_id));
CREATE TABLE sales(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,party_id INTEGER NOT NULL REFERENCES parties(id),bill_date TEXT NOT NULL,due_days INTEGER NOT NULL CHECK(due_days>=0),due_date TEXT NOT NULL,remarks TEXT,status TEXT NOT NULL CHECK(status IN('draft','posted','cancelled')),journal_id INTEGER REFERENCES journal_entries(id),invoice_total INTEGER NOT NULL CHECK(invoice_total>=0));
CREATE TABLE sale_items(id INTEGER PRIMARY KEY,sale_id INTEGER NOT NULL REFERENCES sales(id),quality_id INTEGER NOT NULL REFERENCES qualities(id),carats INTEGER NOT NULL CHECK(carats>0),rate TEXT NOT NULL,less_pct TEXT NOT NULL,gross INTEGER NOT NULL CHECK(gross>=0),net INTEGER NOT NULL CHECK(net>=0));
CREATE TABLE sale_adjustments(id INTEGER PRIMARY KEY,sale_id INTEGER NOT NULL REFERENCES sales(id),description TEXT,amount INTEGER NOT NULL);
CREATE TABLE sale_brokerages(id INTEGER PRIMARY KEY,sale_id INTEGER NOT NULL REFERENCES sales(id),item_id INTEGER REFERENCES sale_items(id),broker_id INTEGER NOT NULL REFERENCES parties(id),mode TEXT NOT NULL CHECK(mode IN('percent','fixed')),input_value TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0));
CREATE TABLE opening_balances(id INTEGER PRIMARY KEY,opening_date TEXT NOT NULL,journal_id INTEGER REFERENCES journal_entries(id),description TEXT);
CREATE TABLE stock_lots(id INTEGER PRIMARY KEY,quality_id INTEGER NOT NULL REFERENCES qualities(id),purchase_item_id INTEGER UNIQUE REFERENCES purchase_items(id),opening_id INTEGER REFERENCES opening_balances(id),acquired_date TEXT NOT NULL,original_carats INTEGER NOT NULL CHECK(original_carats>0),original_cost INTEGER NOT NULL CHECK(original_cost>=0),remaining_carats INTEGER NOT NULL CHECK(remaining_carats BETWEEN 0 AND original_carats),remaining_cost INTEGER NOT NULL CHECK(remaining_cost BETWEEN 0 AND original_cost),CHECK((purchase_item_id IS NULL)<>(opening_id IS NULL)),CHECK(remaining_carats>0 OR remaining_cost=0));
CREATE TABLE sale_stock_allocations(id INTEGER PRIMARY KEY,sale_item_id INTEGER NOT NULL REFERENCES sale_items(id),lot_id INTEGER NOT NULL REFERENCES stock_lots(id),carats INTEGER NOT NULL CHECK(carats>0),cost INTEGER NOT NULL CHECK(cost>=0),mode TEXT NOT NULL CHECK(mode IN('fifo','manual')),active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE stock_movements(id INTEGER PRIMARY KEY,lot_id INTEGER NOT NULL REFERENCES stock_lots(id),movement_date TEXT NOT NULL,carats_delta INTEGER NOT NULL,cost_delta INTEGER NOT NULL,source_type TEXT NOT NULL,source_id INTEGER NOT NULL);
CREATE TABLE open_items(id INTEGER PRIMARY KEY,party_id INTEGER NOT NULL REFERENCES parties(id),account_id INTEGER NOT NULL REFERENCES accounts(id),kind TEXT NOT NULL CHECK(kind IN('purchase','sale','brokerage','opening_payable','opening_receivable')),purchase_id INTEGER REFERENCES purchases(id),sale_id INTEGER REFERENCES sales(id),brokerage_id INTEGER REFERENCES sale_brokerages(id),opening_id INTEGER REFERENCES opening_balances(id),reference TEXT NOT NULL,bill_date TEXT NOT NULL,due_date TEXT,amount INTEGER NOT NULL CHECK(amount>=0),active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE payments(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,party_id INTEGER NOT NULL REFERENCES parties(id),payment_date TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('pay','receive')),fund_account_id INTEGER NOT NULL REFERENCES accounts(id),amount INTEGER NOT NULL CHECK(amount>0),mode TEXT NOT NULL,reference TEXT,remarks TEXT,status TEXT NOT NULL CHECK(status IN('draft','posted','cancelled')),journal_id INTEGER REFERENCES journal_entries(id));
CREATE TABLE payment_allocations(id INTEGER PRIMARY KEY,payment_id INTEGER NOT NULL REFERENCES payments(id),open_item_id INTEGER NOT NULL REFERENCES open_items(id),amount INTEGER NOT NULL CHECK(amount>0),active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE advances(id INTEGER PRIMARY KEY,party_id INTEGER NOT NULL REFERENCES parties(id),payment_id INTEGER REFERENCES payments(id),opening_id INTEGER REFERENCES opening_balances(id),account_id INTEGER NOT NULL REFERENCES accounts(id),direction TEXT NOT NULL CHECK(direction IN('paid','received')),amount INTEGER NOT NULL CHECK(amount>0),active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE advance_allocations(id INTEGER PRIMARY KEY,advance_id INTEGER NOT NULL REFERENCES advances(id),open_item_id INTEGER NOT NULL REFERENCES open_items(id),amount INTEGER NOT NULL CHECK(amount>0),allocation_date TEXT NOT NULL,journal_id INTEGER REFERENCES journal_entries(id),active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE loans(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,party_id INTEGER NOT NULL REFERENCES parties(id),kind TEXT NOT NULL CHECK(kind IN('taken','given')),principal INTEGER NOT NULL CHECK(principal>0),rate TEXT NOT NULL,frequency TEXT NOT NULL CHECK(frequency IN('monthly','yearly')),loan_date TEXT NOT NULL,return_date TEXT,opening_id INTEGER REFERENCES opening_balances(id),fund_account_id INTEGER REFERENCES accounts(id),journal_id INTEGER REFERENCES journal_entries(id),status TEXT NOT NULL CHECK(status IN('open','closed','cancelled')),remarks TEXT);
CREATE TABLE loan_interest_entries(id INTEGER PRIMARY KEY,loan_id INTEGER NOT NULL REFERENCES loans(id),entry_date TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('accrual','payment','opening')),amount INTEGER NOT NULL CHECK(amount>=0),fund_account_id INTEGER REFERENCES accounts(id),journal_id INTEGER REFERENCES journal_entries(id),active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE loan_settlements(id INTEGER PRIMARY KEY,loan_id INTEGER NOT NULL REFERENCES loans(id),settlement_date TEXT NOT NULL,principal INTEGER NOT NULL CHECK(principal>0),interest INTEGER NOT NULL CHECK(interest>=0),fund_account_id INTEGER NOT NULL REFERENCES accounts(id),journal_id INTEGER REFERENCES journal_entries(id),active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE UNIQUE INDEX one_active_settlement ON loan_settlements(loan_id) WHERE active=1;
CREATE TABLE fund_transfers(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,transfer_date TEXT NOT NULL,source_account INTEGER NOT NULL REFERENCES accounts(id),destination_account INTEGER NOT NULL REFERENCES accounts(id),amount INTEGER NOT NULL CHECK(amount>0),journal_id INTEGER REFERENCES journal_entries(id),status TEXT NOT NULL CHECK(status IN('posted','cancelled')),CHECK(source_account<>destination_account));
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY,entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,action TEXT NOT NULL,reason TEXT,before_json TEXT,after_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX fifo_lots ON stock_lots(quality_id,acquired_date,id);
CREATE INDEX journal_dates ON journal_entries(entry_date,status);
CREATE INDEX journal_accounts ON journal_lines(account_id,journal_id);
CREATE INDEX open_party ON open_items(party_id,bill_date,id);
CREATE INDEX payment_bill ON payment_allocations(open_item_id,active);
CREATE INDEX advance_bill ON advance_allocations(open_item_id,active);
CREATE INDEX stock_dates ON stock_movements(lot_id,movement_date);
INSERT INTO schema_migrations(version) VALUES(1);
INSERT INTO company_settings VALUES('global_hike_pct','5');
INSERT INTO accounts(code,name,kind,control) VALUES ('CASH','Cash in Hand','asset',1),('INV','Inventory','asset',1),('AR','Receivables','asset',1),('AP','Payables','liability',1),('BROKER','Brokerage Payable','liability',1),('ADV_PAID','Supplier Advances','asset',1),('ADV_REC','Customer Advances','liability',1),('LOAN_G','Loans Given','asset',1),('LOAN_T','Loans Taken','liability',1),('INT_AR','Interest Receivable','asset',1),('INT_AP','Interest Payable','liability',1),('CAP','Capital','equity',0),('DRAW','Drawings','equity',0),('RE','Retained Earnings','equity',0),('SALES','Sales','income',1),('COGS','Cost of Goods Sold','expense',1),('BROKER_EXP','Brokerage Expense','expense',1),('INT_INC','Interest Income','income',1),('INT_EXP','Interest Expense','expense',1),('RENT','Rent','expense',0),('SALARY','Salary','expense',0),('OTHER_EXP','Other Expenses','expense',0),('OTHER_INC','Other Income','income',0);
